_UNKNOWN_CREDITOR = frozenset({"unknown", "unknown creditor", "n/a", "na"})


def _placeholder_key(creditor: str) -> str:
    """Case- and whitespace-insensitive form used to match filler creditor tokens."""
    return re.sub(r"\s+", " ", (creditor or "").strip()).lower()


def is_junk_creditor_name(creditor: str) -> bool:
    name = (creditor or "").strip()
    if not name:
        return True
    if not is_plausible_creditor_line(name):
        return True
    # Bureaus emit filler tokens in mixed case ("Unknown Creditor", "N/A"),
    # so compare case-insensitively.
    if _placeholder_key(name) in _UNKNOWN_CREDITOR:
        return True

