def is_plausible_creditor_line(line: str) -> bool:
    line = line.strip()
    if len(line) < 2 or len(line) > 80:
        return False
    if _SKIP_CREDITOR_LINES.match(line):
        return False
    if is_city_state_line(line):
        return False
    if re.match(r"^\d{3}[-\s]?\d{2}[-\s]?\d{4}$", line):
        return False
    # Amount / percentage value lines are never creditor names. Match the whole
    # line (or a leading currency amount) so that creditors whose names merely
    # start with a digit ("1ST ADVANTAGE FCU") are not discarded with them.
    if re.fullmatch(r"[\d\$\.,\s%]+", line):
        return False
    if re.match(r"^\$\s*[\d\.,]", line):
        return False
    if line.lower().startswith("http"):
        return False
    return bool(re.search(r"[A-Za-z]", line))

